const SH_R = [-6, 22, 0], SH_L = [6, 22, 0]; // shoulders
const ARM_LEN = 10, ARM_R = 2.15, FIST_GAP = .2;
const ARM_HW = 2, PALM_A = ARM_LEN - 2, FLAT = 3, ALONG = 2.5; // half an arm's width, and how far down it the middle of the hand is, how much a palm that isn't flat on the gun costs, and an arm that points away from the gun's line
