    const dx = SH_R[0] + d1.x * a - SH_L[0] - d2.x * b, dy = SH_R[1] + d1.y * a - SH_L[1] - d2.y * b, dz = SH_R[2] + d1.z * a - SH_L[2] - d2.z * b;
